import sys,os,json,base64,zlib,shutil,subprocess,hashlib
from pathlib import Path
root=next(Path('/kaggle/input').rglob('evaluate_auth_features.py')).parents[1]
code=Path('/kaggle/working/code');shutil.copytree(root,code,dirs_exist_ok=True)
for name,value in json.loads(zlib.decompress(base64.b64decode(''))).items():
 p=code/name;p.parent.mkdir(parents=True,exist_ok=True);p.write_text(value)
(code/'tests/__init__.py').touch()
os.environ['PYTHONPATH']=str(code)+os.pathsep+str(code/'tests')
subprocess.run([sys.executable,'-m','pip','install','-e',str(code),'pytest'],check=True)
out=Path('/kaggle/working/out');out.mkdir(exist_ok=True)
excluded=['tests/test_comp3.py','tests/test_letter_head.py','tests/test_bank_report.py','tests/test_kaggle_kill_test_run.py']
(out/'cloud_test_scope.json').write_text(json.dumps(dict(excluded=excluded,reason='Raw EEG absent; credential path test incompatible with immutable account path',scope='portable repository suite, explicitly excludes unavailable raw/path checks')))
subprocess.run([sys.executable,'-m','pytest','-q']+['--ignore='+p for p in excluded],cwd=code,check=True)
from scipy.stats import beta,binom
rows=[]
for n in (6,20,33,36,59,69,100,200,500):
 upper=[1. if k==n else float(beta.ppf(.95,k+1,n-k)) for k in range(n+1)]
 max_k=max([k for k,u in enumerate(upper) if u<=.05],default=-1)
 rows.append(dict(n=n,upper95_zero=upper[0],upper95_one=upper[1],upper95_two=upper[2],max_alarms_for_upper5=max_k,prob_certify_if_true_rate={str(p):0. if max_k<0 else float(binom.cdf(max_k,n,p)) for p in (.01,.03,.05)},rank_resolution=1/(n+1)))
(out/'sample_design.json').write_text(json.dumps(dict(rows=rows,assumptions='IID independent Bernoulli evaluation and one-sided95% exact intervals. Rank resolution assumes exchangeability. Not EEG/per-user simultaneous guarantees.',status='design sensitivity, no empirical EEG performance or frozen allocation'),indent=2))
(out/'config.json').write_text(json.dumps(dict(seed=20261012,source_overlay='b910db5 plus network_character.py/test overlay fingerprint',runner_sha256=hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),stage='portable tests and sample design only; no EEG/model fitting'),indent=2))
